// Fix 6 (adversary finding 7): a web turn sends explicit tool lists, the
// desktop's for the same gateway answer. Cases generated BY the desktop's
// controller (web/scripts/gen_tool_policy_parity.py).
import { readFileSync } from "node:fs";
import { resolve } from "node:path";
import { describe, expect, it } from "vitest";

import { buildRunInputData } from "./run_input";
import { runToolsFromDiscovery } from "./tool_policy";

type Case = { name: string; discovery: unknown; expected: unknown };
const cases: Case[] = JSON.parse(readFileSync(resolve(__dirname, "__fixtures__/tool_policy_parity.json"), "utf8"));

describe("runToolsFromDiscovery (parity with controller.allowed_tools_for_run / tool_policy_for_run)", () => {
  for (const c of cases) {
    it(c.name, () => {
      expect(runToolsFromDiscovery(c.discovery)).toEqual(c.expected);
    });
  }
  it("a tool without approval_default asks (the web has no local list)", () => {
    expect(runToolsFromDiscovery({ items: [{ name: "mystery" }] }).tool_policy).toEqual({ auto_approve_tools: [], require_approval_tools: ["mystery"] });
  });
  it("an answer without items is an error, not 'no tools'", () => {
    expect(() => runToolsFromDiscovery({ error: "down" })).toThrow(/no items/);
  });
  it("the lists ride the run input the way the desktop's builder places them", () => {
    const t = runToolsFromDiscovery(cases[0].discovery);
    const input = buildRunInputData({ prompt: "hi", ...t }) as { tools: string[]; _runtime: Record<string, unknown> };
    expect(input.tools).toEqual(t.allowed_tools);
    expect(input._runtime.allowed_tools).toEqual(t.allowed_tools);
    expect(input._runtime.tool_policy).toEqual(t.tool_policy);
  });
});
